complex.c:
typedef struct {
    int x;
    int y;
    int z;
} Point3D;

Point3D make_point(int x, int y, int z) {
    Point3D p;
    p.x = x;
    p.y = y;
    p.z = z;
    return p;
}

int main() {
    Point3D p = make_point(1, 2, 3);
    return p.x + p.y + p.z;
}
